local function a(b,c,d)b[c]=b[c]or{}table.insert(b[c],d)end;Doctor.register({id='dependencias',title='Dependencias de los recursos',run=function(e)local f=Doctor.resources(e)local g=GetConvar('onesync','off')local h=Doctor.serverBuild()local i=tonumber(GetConvar('sv_enforceGameBuild',''))local j,k,l,m={},{},{},{}for n,o in ipairs(f.list)do local p=Doctor.info(e,o)local q=Doctor.isRunning(p.state)for n,r in ipairs(p.deps)do if r:sub(1,1)=='/'then if not q then local s,t=r:match('^/([%w_]+):?(.*)$')if s=='onesync'and g=='off'then k[#k+1]=o elseif s=='server'and h and tonumber(t)and h<tonumber(t)then a(l,t,o)elseif s=='gameBuild'and tonumber(t)and(i or 0)<tonumber(t)then a(m,t,o)end end else local u=r:match('^%s*([^%s]+)')local v=GetResourceState(u)if not Doctor.isInstalled(e,u)then a(j,u,o)elseif q and not Doctor.isRunning(v)then e:add({severity='error',title=('%s está iniciado pero su dependencia %s no'):format(o,u),where=o..'/fxmanifest.lua',why=('%s declara que necesita %s, que ahora está en estado "%s". Puede fallar en cuanto la use.'):format(o,u,v),fix={('Inicia la dependencia: ensure %s'):format(u),('En server.cfg, pon "ensure %s" antes de "ensure %s".'):format(u,o)}})end end end end;for u,w in pairs(j)do e:add({severity='advertencia',title=('Falta el recurso %s'):format(u),where=w[1]..'/fxmanifest.lua',why=('Lo piden %d recurso(s) que no están iniciados: %s. Mientras falte, FiveM no los dejará arrancar.'):format(#w,Doctor.nameList(w)),fix={('Si usas esos recursos, instala %s en la carpeta resources y añade "ensure %s" antes que ellos.'):format(u,u),'Si no los usas, puedes ignorar este aviso o quitarlos del servidor.'}})end;if#k>0 then e:add({severity='advertencia',title='Hay recursos que necesitan OneSync y está desactivado',where='server.cfg (onesync)',why=('Piden OneSync y no están iniciados: %s.'):format(Doctor.nameList(k)),fix={'Activa OneSync arrancando el servidor con "+set onesync on" (o desde txAdmin) y reinicia.'}})end;for x,w in pairs(l)do e:add({severity='advertencia',title=('Hay recursos que piden el servidor %s o superior'):format(x),where=w[1]..'/fxmanifest.lua',why=('Tu servidor es la compilación %d. No se iniciarán: %s.'):format(h,Doctor.nameList(w)),fix={'Actualiza los artefactos del servidor FXServer a una compilación reciente.'}})end;for x,w in pairs(m)do e:add({severity='advertencia',title=('Hay recursos que piden la versión del juego %s o superior'):format(x),where='server.cfg (sv_enforceGameBuild)',why=(i and('Tienes fijada la versión %d. '):format(i)or'No tienes fijada ninguna versión del juego. ')..('No se iniciarán: %s.'):format(Doctor.nameList(w)),fix={('Añade "set sv_enforceGameBuild %s" (o superior) a server.cfg y reinicia el servidor.'):format(x)}})end;for y,z in pairs(f.provides)do local q={}for n,d in ipairs(z)do if Doctor.isRunning(GetResourceState(d))then q[#q+1]=d end end;if#q>1 then e:add({severity='advertencia',title=('Varios recursos iniciados ocupan el nombre %s'):format(y),where=q[1]..'/fxmanifest.lua (provide)',why=('%s responden como %s. Los scripts que lo usan pueden hablar con el equivocado.'):format(table.concat(q,', '),y),fix={'Deja iniciado solo uno de ellos y quita el "ensure" de los demás.'}})end end;if f.truncated then e:add({severity='informacion',title='No se revisaron todos los recursos',where='config.lua (Config.Limits.maxResources)',why=('El servidor tiene %d recursos y el límite es %d.'):format(f.total,Config.Limits.maxResources),fix={'Sube Config.Limits.maxResources si quieres revisarlos todos.'}})end end})